-- Migrated from hyprland.conf (Hyprland 0.55+ deprecated the hyprlang/.conf
-- format in favor of Lua). This is a 1:1 port of the old hyprland.conf; see
-- git history for the original if you need to compare.
--
-- Verified against the locally installed Lua API stub
-- (/usr/share/hypr/stubs/hl.meta.lua, generated by this machine's own
-- Hyprland 0.56.0 build) and the shipped example config
-- (/usr/share/hypr/hyprland.lua). Two spots are best-effort because their
-- exact call shape isn't confirmable from those local sources alone —
-- marked BEST-EFFORT below. Check https://wiki.hypr.land/Configuring/Basics/Binds/
-- if either misbehaves after reload.

------------------
---- MONITORS ----
------------------

-- Monitor positions + per-workspace monitor assignment live in monitors.lua,
-- itself a symlink to monitors-home.lua or monitors-work.lua, flipped by
-- bin/toggle-monitors.sh (mirrors the old monitors.conf -> monitors-{home,work}.conf setup).
require("monitors")

-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

-- NVIDIA / Renderização Hardware
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("GBM_BACKEND", "nvidia-drm")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.env("NVD_BACKEND", "direct")

-- Forçar Wayland Nativo nos Toolkits & Apps
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("MOZ_ENABLE_WAYLAND", "1")

-- Aparência e Sessão XDG
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_STYLE_OVERRIDE", "kvantum")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XCURSOR_THEME", "Bibata-Modern-Ice")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_THEME", "Bibata-Modern-Ice")
hl.env("HYPRCURSOR_SIZE", "24")

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
	-- 1. Exporta ambiente de display e compositor para D-Bus e Systemd
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP=Hyprland")
	hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")

	-- 2. Inicia o cofre (o agente polkit é o embutido no Noctalia)
	hl.exec_cmd("gnome-keyring-daemon --start --components=secrets,ssh")

	-- 3. Cursor
	hl.exec_cmd("hyprctl setcursor Bibata-Modern-Ice 24")

	-- 4. Daemons do ambiente gráfico (wallpaper, idle e lockscreen ficam com o Noctalia)
	-- hl.exec_cmd("quickshell")
	hl.exec_cmd("noctalia")

	-- 5. Gerenciador de Clipboard
	hl.exec_cmd("wl-paste --type text --watch cliphist store")
	hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)

