--------------------------------
---- WINDOW / LAYER RULES ------
--------------------------------

-- Cinny: open silently on the special "chat" workspace
hl.window_rule({
	name = "cinny-scratchpad",
	match = { class = "^(cinny)$" },
	workspace = "special:chat silent",
})

-- Noctalia Settings
hl.window_rule({
	match = { class = "dev.noctalia.Noctalia" },
	float = true,
	size = { 1080, 920 },
})

hl.layer_rule({
	name = "noctalia",
	match = {
		namespace = "^noctalia-(bar-.+|notification|dock|panel|attached-panel|osd|window-switcher)$",
	},
	no_anim = true,
	ignore_alpha = 0.5,
	blur = true,
	blur_popups = true,
})

hl.window_rule({
	name = "openlogi-actions-ring",
	match = { class = "^(openlogi-action-ring.*)$" },
	float = true,
	move = { "(cursor_x-(window_w*0.5))", "(cursor_y-(window_h*0.5))" },
	border_size = 0,
	no_blur = true,
	no_shadow = true,
	no_anim = true,
	stay_focused = true,
})

