---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

local ipc = "noctalia msg "

-- Core binds
hl.bind(mainMod .. " + Space", hl.dsp.exec_cmd(ipc .. "panel-toggle launcher"))
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd(ipc .. "panel-toggle control-center"))
hl.bind(mainMod .. " + comma", hl.dsp.exec_cmd(ipc .. "settings-toggle"))
hl.bind(mainMod .. " + Tab", hl.dsp.exec_cmd(ipc .. "window-switcher"))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd(ipc .. "panel-toggle clipboard"))

-- Media keys
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd(ipc .. "volume-up"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd(ipc .. "volume-down"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd(ipc .. "volume-mute"))
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd(ipc .. "brightness-up"))
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd(ipc .. "brightness-down"))

-- General Binds
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("foot"))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- hl.bind(mainMod .. " + W", hl.dsp.exit())
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("dolphin"))
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
-- hl.bind(mainMod .. " + Space", hl.dsp.global("quickshell:launcherToggle"))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd(ipc .. "session lock"))
hl.bind(mainMod .. " + Y", hl.dsp.window.pseudo()) -- dwindle
hl.bind(mainMod .. " + U", hl.dsp.layout("togglesplit")) -- dwindle

-- BEST-EFFORT: old `fullscreen, <mode>` dispatcher (0 = fullscreen, 1 = maximize).
-- Arg shape (bare number vs a table) isn't confirmed locally — check behavior after reload.
hl.bind(mainMod .. " + Z", hl.dsp.window.fullscreen(1))
hl.bind(mainMod .. " + SHIFT + Z", hl.dsp.window.fullscreen(0))


hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("~/.config/hypr/bin/toggle-monitors.sh"))

-- Toggle/hide Cinny (scratchpad)
hl.bind(mainMod .. " + C", hl.dsp.workspace.toggle_special("chat"))

-- Screenshot -> Satty
hl.bind(
	mainMod .. " + P",
	hl.dsp.exec_cmd('grim -g "$(slurp)" - | satty --filename - --early-exit --copy-command "wl-copy"')
)
hl.bind(
	mainMod .. " + SHIFT + P",
	hl.dsp.exec_cmd(
		'grim -g "$(slurp)" - | satty --filename - --fullscreen --output-filename ~/Pictures/Screenshots/satty-$(date +%Y%m%d-%H%M%S).png'
	)
)
hl.bind(
	mainMod .. " + CTRL + P",
	hl.dsp.exec_cmd(
		'grim -g "$(hyprctl activewindow -j | jq -r \'"\\(.at[0]),\\(.at[1]) \\(.size[0])x\\(.size[1])"\')" - | satty --filename - --early-exit --copy-command "wl-copy"'
	)
)

hl.bind(mainMod .. " + R", hl.dsp.exec_cmd('hyprctl reload && notify-send "Hyprland" "Config reloaded"'))

-- Kill mode (xkill-like: click on a window to kill it, Escape to cancel)
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("hyprctl kill"))

